// Parse Groq JSON response safely
const raw = $input.item.json.choices[0].message.content.trim();

let parsed;
try {
  // Strip any accidental markdown fences
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Return structured error so Streamlit can handle gracefully
  return [{
    json: {
      success: false,
      error: 'Groq returned invalid JSON',
      raw_response: raw
    }
  }];
}

return [{
  json: {
    success: true,
    ...parsed,
    raw_stats: $('Aggregate: All Table Stats').item.json.all_stats
  }
}];
